/// - `u32` is varint; `u32::MAX` needs 5 bytes (`varint_max::<u32>()`).
/// - `u64` is varint; `u64::MAX` needs 10 bytes (LEB128: `ceil(64/7) = 10`,
///   `varint_max::<u64>() = (64 + 7 - 1) / 7 = 10`).
/// - `bool` is 1 byte (true=1, false=0).
