        self.fail_next_persist.store(true, Ordering::SeqCst);
    }

    #[cfg(test)]
    pub(crate) fn consume_persist_failure_for_test(&self) -> bool {
        self.fail_next_persist.swap(false, Ordering::SeqCst)
    }

