    #[cfg(test)]
    pub(crate) fn fail_next_batch_commit_for_test(&self) {
        self.fail_next_batch_commit.store(true, Ordering::SeqCst);
    }

    /// Test-only consumer: returns and clears the batch-commit fault flag.
