    /// exactly once; a subsequent real commit succeeds normally.
    #[cfg(test)]
    pub(crate) fn consume_batch_commit_failure_for_test(&self) -> bool {
        self.fail_next_batch_commit.swap(false, Ordering::SeqCst)
    }
}

impl Drop for FjallJournal {
    fn drop(&mut self) {
        // Drop cannot propagate errors from close(), so callers who need
        // guaranteed durability must call close() explicitly.
        // Drop only releases the process lock here.
    }
}

